<?php
declare(strict_types=1);
require_once __DIR__ . '/bootstrap/app.php';
$user=pf_require_login($pdo);
$stmt=$pdo->prepare("SELECT id,currency FROM pf_wallets WHERE user_id=? AND wallet_type='ADVERTISER' ORDER BY currency");$stmt->execute([(int)$user['id']]);$wallets=$stmt->fetchAll();$entries=[];$balances=[];
foreach($wallets as $wallet){$sum=$pdo->prepare('SELECT COALESCE(SUM(amount),0) FROM pf_wallet_ledger WHERE wallet_id=?');$sum->execute([(int)$wallet['id']]);$balances[$wallet['currency']]=(float)$sum->fetchColumn();$history=$pdo->prepare('SELECT entry_type,amount,currency,description,created_at FROM pf_wallet_ledger WHERE wallet_id=? ORDER BY id DESC LIMIT 50');$history->execute([(int)$wallet['id']]);$entries[$wallet['currency']]=$history->fetchAll();}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Advertiser wallet | PoketFlow</title><link rel="stylesheet" href="assets/marketplace.css"></head><body>
<header class="topbar"><a class="brand" href="index.php"><span class="brand-mark">P</span><span>Poket<span>Flow</span></span></a><nav><a href="dashboard.php">Dashboard</a><a href="campaigns.php">Campaigns</a><a href="funding.php">Add funds</a><a href="logout.php">Sign out</a></nav></header>
<main class="container"><section class="welcome"><p class="eyebrow">ADVERTISER FINANCES</p><h1>Your advertising wallet</h1><p class="muted">Your balance is calculated from the advertiser ledger. Historical worker records remain preserved separately and are not available as new platform features.</p></section>
<?php foreach($wallets as $wallet):$currency=$wallet['currency'];?><section class="panel"><p class="eyebrow"><?=pf_e($currency)?> AVAILABLE BALANCE</p><div class="metric"><?=pf_e($currency)?> <?=number_format($balances[$currency]??0,2)?></div><p><a class="button primary" href="funding.php">Add funds</a> <a class="button" style="background:#fff;border:1px solid var(--line)" href="campaigns.php">Manage campaigns</a></p><h2>Transaction history</h2><div style="overflow:auto"><table style="width:100%;border-collapse:collapse;text-align:left"><thead><tr><th>Type</th><th>Description</th><th>Amount</th><th>Date</th></tr></thead><tbody><?php foreach($entries[$currency] as $entry):?><tr><td><?=pf_e($entry['entry_type'])?></td><td><?=pf_e((string)$entry['description'])?></td><td><?=((float)$entry['amount']>=0?'+':'')?><?=pf_e($entry['currency'])?> <?=number_format((float)$entry['amount'],2)?></td><td><?=pf_e($entry['created_at'])?></td></tr><?php endforeach;?><?php if(!$entries[$currency]):?><tr><td colspan="4">No advertiser transactions yet.</td></tr><?php endif;?></tbody></table></div></section><?php endforeach;?>
<?php if(!$wallets):?><section class="panel"><h2>Advertiser wallet is being prepared</h2><p class="muted">Contact support if this message persists.</p></section><?php endif;?></main></body></html>
